    "PostToolUse": [
      {"matcher": "Task", "hooks": [{"type": "command", "command": %q}]},
      {"matcher": "TodoWrite", "hooks": [{"type": "command", "command": %q}]}
    ]
  }
}`, stop, pre, post, todo))

	if got := CheckHookConfig(context.Background()); got != HooksOutdated {
		t.Errorf("CheckHookConfig() = %v, want HooksOutdated", got)
	}
